   [206]={next_id=207, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芙兰朵的呼吸停滞了一瞬，不是她不想呼吸，而是女人周身涌现的狂暴力量让她无法呼吸。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [207]={next_id=208, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="女人丝毫不在意芙兰朵的窒息，她直接向整个广场被控制的士兵们下达了命令。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
