   [209]={next_id=210, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="整个广场、整座城市里，那些被控制的士兵如同听到了某种远古的号角，他们极其整齐划一地转身，迈着机械且狂热的步伐，犹如黑色的蚁群，向着码头方向的中央舰队疯狂涌去。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
